std::vector<double> get_rho(const walberla::gpu::GPUField<double> *field, const std::vector<double> &pos, const double density, uint gl) {
  if (pos.empty()) {
    return {};
  }
  uint n_pos = static_cast<uint>(pos.size() / 3ul);
  walberla::CellInterval ci = field->xyzSize();
  ci.expand(walberla::cell_idx_c(gl));
  thrust::device_vector<double> dev_pos(pos.begin(), pos.end());
  double *dev_pos_ptr = thrust::raw_pointer_cast(dev_pos.data());
  thrust::device_vector<double> dev_out(n_pos);
  double *dev_out_ptr = thrust::raw_pointer_cast(dev_out.data());
  const double *RESTRICT const _data_pdfs{field->dataAt(ci.xMin(), ci.yMin(), ci.zMin(), 0)};
  /* ci.xSize() == _size_pdfs_0 */
  /* ci.ySize() == _size_pdfs_1 */
  /* ci.zSize() == _size_pdfs_2 */
  /* field->fSize() == 19 */
  const int64_t _stride_pdfs_0{int64_t(field->xStride())};
  const int64_t _stride_pdfs_1{int64_t(field->yStride())};
  const int64_t _stride_pdfs_2{int64_t(field->zStride())};
  const int64_t _stride_pdfs_3{int64_t(field->fStride())};
  const double *RESTRICT const _data_pos{dev_pos_ptr};
  /* n_pos == _size_pos_0 */
  /* 3 == 3 */
  const int64_t _stride_pos_0{int64_t(3)};
  const int64_t _stride_pos_1{int64_t(1)};
  double *RESTRICT const _data_out1{dev_out_ptr};
  const int64_t _size_out1_0{int64_t(n_pos)};
  const int64_t _stride_out1_0{int64_t(1)};
  const int64_t ghost_layers = int64_t(gl);
  {
    const dim3 __block_size{256, 1, 1};
    const std::tuple<uint32_t, uint32_t, uint32_t> __work_items{_size_out1_0, 1LL, 1LL};
    const dim3 __grid_size{(std::get<0>(__work_items) + __block_size.x - 1) / __block_size.x, (std::get<1>(__work_items) + __block_size.y - 1) / __block_size.y, (std::get<2>(__work_items) + __block_size.z - 1) / __block_size.z};
    /* clang-format off */
        /* [pystencils-sfg] Formatting may add illegal spaces between angular brackets in `<<< >>>` */
        walberla::lbm::accessor::Interpolation::kernels::get_rho<<< __grid_size, __block_size, 0 >>>(_data_out1, _data_pdfs, _data_pos, _size_out1_0, _stride_out1_0, _stride_pdfs_0, _stride_pdfs_1, _stride_pdfs_2, _stride_pdfs_3, _stride_pos_0, _stride_pos_1, density, ghost_layers);
    /* clang-format on */
  }
  std::vector<double> out(n_pos);
  thrust::copy(dev_out.begin(), dev_out.end(), out.data());
  return out;
}

std::vector<double> get_vel(const walberla::gpu::GPUField<double> *field, const std::vector<double> &pos, uint gl) {
  if (pos.empty()) {
