  }
  uint n_pos = static_cast<uint>(pos.size() / 3ul);
  walberla::CellInterval ci = field->xyzSize();
  ci.expand(walberla::cell_idx_c(gl));
  thrust::device_vector<double> dev_pos(pos.begin(), pos.end());
  double *dev_pos_ptr = thrust::raw_pointer_cast(dev_pos.data());
  thrust::device_vector<double> dev_out(3u * n_pos);
  double *dev_out_ptr = thrust::raw_pointer_cast(dev_out.data());
  const double *RESTRICT const _data_vec{field->dataAt(ci.xMin(), ci.yMin(), ci.zMin(), 0)};
  /* ci.xSize() == _size_vec_0 */
  /* ci.ySize() == _size_vec_1 */
  /* ci.zSize() == _size_vec_2 */
  /* field->fSize() == 3 */
  const int64_t _stride_vec_0{int64_t(field->xStride())};
  const int64_t _stride_vec_1{int64_t(field->yStride())};
  const int64_t _stride_vec_2{int64_t(field->zStride())};
  const int64_t _stride_vec_3{int64_t(field->fStride())};
  const double *RESTRICT const _data_pos{dev_pos_ptr};
  /* n_pos == _size_pos_0 */
  /* 3 == 3 */
  const int64_t _stride_pos_0{int64_t(3)};
  const int64_t _stride_pos_1{int64_t(1)};
  double *RESTRICT const _data_out3{dev_out_ptr};
  const int64_t _size_out3_0{int64_t(n_pos)};
  /* 3 == 3 */
  const int64_t _stride_out3_0{int64_t(3)};
  const int64_t _stride_out3_1{int64_t(1)};
  const int64_t ghost_layers = int64_t(gl);
  {
    const dim3 __block_size{256, 1, 1};
    const std::tuple<uint32_t, uint32_t, uint32_t> __work_items{_size_out3_0, 1LL, 1LL};
    const dim3 __grid_size{(std::get<0>(__work_items) + __block_size.x - 1) / __block_size.x, (std::get<1>(__work_items) + __block_size.y - 1) / __block_size.y, (std::get<2>(__work_items) + __block_size.z - 1) / __block_size.z};
    /* clang-format off */
        /* [pystencils-sfg] Formatting may add illegal spaces between angular brackets in `<<< >>>` */
        walberla::lbm::accessor::Interpolation::kernels::get_vel<<< __grid_size, __block_size, 0 >>>(_data_out3, _data_pos, _data_vec, _size_out3_0, _stride_out3_0, _stride_out3_1, _stride_pos_0, _stride_pos_1, _stride_vec_0, _stride_vec_1, _stride_vec_2, _stride_vec_3, ghost_layers);
    /* clang-format on */
  }
  std::vector<double> out(3u * n_pos);
  thrust::copy(dev_out.begin(), dev_out.end(), out.data());
  return out;
}

/** @brief Calculate interpolation weights. */
static __forceinline__ __device__ void calculate_weights(
    double const *RESTRICT const pos, int *RESTRICT const corner,
    double *RESTRICT const weights, uint gl) {
#pragma unroll
  for (int dim = 0; dim < 3; ++dim) {
    auto const fractional_index = pos[dim] - double{0.5};
    auto const nmp = floor(fractional_index);
    auto const distance = fractional_index - nmp - double{0.5};
    corner[dim] = static_cast<int>(nmp) + static_cast<int>(gl);
    weights[dim * 2 + 0] = double{0.5} - distance;
    weights[dim * 2 + 1] = double{0.5} + distance;
  }
}

__global__ void kernel_add_force(
    walberla::gpu::FieldAccessor<double> force,
    double const *RESTRICT const pos, double const *RESTRICT const forces,
    uint n_pos, uint gl) {
  uint const pos_index = blockDim.x * blockIdx.x + threadIdx.x;
  force.set({0u, 0u, 0u}, {0u, 0u, 0u});
  if (force.isValidPosition() and pos_index < n_pos) {
    auto const array_offset = pos_index * uint(3u);
    int corner[3];
    double weights[3][2];
    calculate_weights(pos + array_offset, corner, &weights[0][0], gl);
#pragma unroll
    for (int i = 0; i < 2; i++) {
      auto const cx = corner[0] + i;
      auto const wx = weights[0][i];
#pragma unroll
      for (int j = 0; j < 2; j++) {
        auto const cy = corner[1] + j;
        auto const wxy = wx * weights[1][j];
#pragma unroll
        for (int k = 0; k < 2; k++) {
          auto const cz = corner[2] + k;
          auto const weight = wxy * weights[2][k];
#pragma unroll
          for (uint cf = 0u; cf < 3u; ++cf) {
            atomicAdd(&force.getNeighbor(cx, cy, cz, cf),
                      weight * forces[array_offset + cf]);
          }
        }
      }
    }
  }
}

void add_force(const walberla::gpu::GPUField<double> *field, const std::vector<double> &pos, const std::vector<double> &forces, uint gl) {
  assert(forces.size() == pos.size());
  if (pos.empty()) {
    return;
  }
  thrust::device_vector<double> dev_pos(pos.begin(), pos.end());
  thrust::device_vector<double> dev_for(forces.begin(), forces.end());
  auto const *dev_pos_ptr = thrust::raw_pointer_cast(dev_pos.data());
  auto const *dev_for_ptr = thrust::raw_pointer_cast(dev_for.data());
  auto const threads_per_block = uint(64u);
  auto const n_pos = static_cast<uint>(pos.size() / 3ul);
  auto const dim_grid = (n_pos + threads_per_block - 1u) / threads_per_block;
  auto const accessor = walberla::gpu::FieldIndexing<double>::withGhostLayerXYZ(*field, gl).gpuAccess();
  /* clang-format off */
      kernel_add_force<<<dim_grid, threads_per_block, 0u, nullptr>>>(accessor, dev_pos_ptr, dev_for_ptr, n_pos, gl);
  /* clang-format on */
}
