        walberla::lbm::accessor::Velocity::kernels::get<<< __grid_size, __block_size, 0 >>>(_data_buf3, _data_force, _data_pdfs, _size_buf3_0, _size_buf3_1, _size_buf3_2, _stride_buf3_0, _stride_buf3_1, _stride_buf3_2, _stride_buf3_3, _stride_force_0, _stride_force_1, _stride_force_2, _stride_force_3, _stride_pdfs_0, _stride_pdfs_1, _stride_pdfs_2, _stride_pdfs_3);
    /* clang-format on */
