walberla::Matrix3<double> reduce(const walberla::gpu::GPUField<double> *pdf_field, const double density) {
  walberla::CellInterval ci = pdf_field->xyzSize();
  thrust::device_vector<double> dev_data(ci.numCells() * 9u);
  double *dev_data_ptr = thrust::raw_pointer_cast(dev_data.data());
  const double *RESTRICT const _data_pdfs{pdf_field->dataAt(ci.xMin(), ci.yMin(), ci.zMin(), 0)};
  /* ci.xSize() == _size_pdfs_0 */
  /* ci.ySize() == _size_pdfs_1 */
  /* ci.zSize() == _size_pdfs_2 */
  /* pdf_field->fSize() == 19 */
  const int64_t _stride_pdfs_0{int64_t(pdf_field->xStride())};
  const int64_t _stride_pdfs_1{int64_t(pdf_field->yStride())};
  const int64_t _stride_pdfs_2{int64_t(pdf_field->zStride())};
  const int64_t _stride_pdfs_3{int64_t(pdf_field->fStride())};
  double *RESTRICT const _data_buf9{dev_data_ptr};
  const int64_t _size_buf9_0{int64_t(ci.xSize())};
  const int64_t _size_buf9_1{int64_t(ci.ySize())};
  const int64_t _size_buf9_2{int64_t(ci.zSize())};
  /* 9 == 9 */
  const int64_t _stride_buf9_0{int64_t(9 * ci.ySize() * ci.zSize())};
  const int64_t _stride_buf9_1{int64_t(9 * ci.zSize())};
  const int64_t _stride_buf9_2{int64_t(9)};
  const int64_t _stride_buf9_3{int64_t(1)};
  {
    const dim3 __block_size{8, 8, 4};
    const std::tuple<uint32_t, uint32_t, uint32_t> __work_items{_size_buf9_0, _size_buf9_1, _size_buf9_2};
    const dim3 __grid_size{(std::get<0>(__work_items) + __block_size.x - 1) / __block_size.x, (std::get<1>(__work_items) + __block_size.y - 1) / __block_size.y, (std::get<2>(__work_items) + __block_size.z - 1) / __block_size.z};
    /* clang-format off */
        /* [pystencils-sfg] Formatting may add illegal spaces between angular brackets in `<<< >>>` */
        walberla::lbm::accessor::PressureTensor::kernels::reduce<<< __grid_size, __block_size, 0 >>>(_data_buf9, _data_pdfs, _size_buf9_0, _size_buf9_1, _size_buf9_2, _stride_buf9_0, _stride_buf9_1, _stride_buf9_2, _stride_buf9_3, _stride_pdfs_0, _stride_pdfs_1, _stride_pdfs_2, _stride_pdfs_3);
    /* clang-format on */
  }
  std::vector<double> out(ci.numCells() * 9u);
  thrust::copy(dev_data.begin(), dev_data.end(), out.data());
  walberla::Matrix3<double> pressure_tensor(double{0});
  for (auto i = uint_t{0u}; i < out.size(); i += 9u) {
    pressure_tensor[0u] += out[i + 0u];
    pressure_tensor[1u] += out[i + 1u];
    pressure_tensor[2u] += out[i + 2u];
    pressure_tensor[3u] += out[i + 3u];
    pressure_tensor[4u] += out[i + 4u];
    pressure_tensor[5u] += out[i + 5u];
    pressure_tensor[6u] += out[i + 6u];
    pressure_tensor[7u] += out[i + 7u];
    pressure_tensor[8u] += out[i + 8u];
  }
  return pressure_tensor * density;
}
